// worker/order.js — pedido do briefing enviado para o WhatsApp da loja.
// Ambiente: WHATSAPP_NUMBER (DDI + DDD + número, só dígitos), SHOP_NAME, PRICE_LABEL, PIX_KEY,
// ORDER_SECRET (assina os links do pedido), ADMIN_TOKEN (painel e exclusão) e,
// opcionalmente, WHATSAPP_TOKEN + WHATSAPP_PHONE_ID para enviar o pedido pelo WhatsApp Cloud API.
const ORDER_STATUSES=['novo','em produção','pago','enviado','cancelado'];
const orderSettings=env=>{const source=env||{};return {shop:cleanText(source.SHOP_NAME)||'FC Livros Mágicos',whatsapp:cleanText(source.WHATSAPP_NUMBER).replace(/[^0-9]/g,''),price:cleanText(source.PRICE_LABEL)||'R$ 49,90',pix:cleanText(source.PIX_KEY),pixCopyPaste:cleanText(source.PIX_COPY_PASTE),secret:cleanText(source.ORDER_SECRET),admin:cleanText(source.ADMIN_TOKEN),token:cleanText(source.WHATSAPP_TOKEN),phoneId:cleanText(source.WHATSAPP_PHONE_ID),storagePersistent:Boolean(source.STORAGE_PERSISTENT)}};
async function readAdminPreferences(env){if(!env||!env.BUCKET)return {};const object=await env.BUCKET.get('admin/settings.json');if(!object)return {};try{const data=await object.json();return data&&typeof data==='object'?data:{}}catch{return {}}}
function normalizeShopWhatsapp(value){let number=cleanText(value).replace(/[^0-9]/g,'');if((number.length===10||number.length===11)&&!number.startsWith('55'))number='55'+number;return number.slice(0,15)}
function sanitizeAdminPreferences(body){const source=body||{};return {shop:cleanText(source.shop).slice(0,80),whatsapp:normalizeShopWhatsapp(source.whatsapp),price:cleanText(source.price).slice(0,40),pix:cleanText(source.pix).slice(0,160),pixCopyPaste:cleanText(source.pixCopyPaste).slice(0,1200)}}
async function saveAdminPreferences(env,body){const data=sanitizeAdminPreferences(body);await env.BUCKET.put('admin/settings.json',JSON.stringify(data),{httpMetadata:{contentType:'application/json'}});return data}
async function resolvedOrderSettings(env){const base=orderSettings(env);const saved=await readAdminPreferences(env);return {...base,shop:cleanText(saved.shop)||base.shop,whatsapp:cleanText(saved.whatsapp)||base.whatsapp,price:cleanText(saved.price)||base.price,pix:saved.pix===undefined?base.pix:cleanText(saved.pix),pixCopyPaste:saved.pixCopyPaste===undefined?base.pixCopyPaste:cleanText(saved.pixCopyPaste)}}
const orderCode=()=>Array.from(crypto.getRandomValues(new Uint8Array(6)),byte=>byte.toString(16).padStart(2,'0')).join('').toUpperCase();
// Token do link: derivado de HMAC(código + segredo). Trocar ORDER_SECRET invalida todos os links.
const orderAccessToken=async(code,secret)=>{const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret||'fc-ordens'),{name:'HMAC',hash:'SHA-256'},false,['sign']);const signature=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(String(code)));return Array.from(new Uint8Array(signature)).slice(0,16).map(byte=>byte.toString(16).padStart(2,'0')).join('')};
const orderCleanCode=code=>String(code||'').toUpperCase().replace(/[^A-F0-9]/g,'').slice(0,16);
const escapeHtml=value=>String(value==null?'':value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function characterSummaryLines(briefing){const data=briefing||{};const main=cleanText(data.name)||'criança';const result=['Principal: '+main+(data.years===''||data.years===undefined||data.years===null?'':' · '+data.years+' anos')];for(const item of (Array.isArray(data.cast)?data.cast:[])){const name=cleanText(item&&item.name);if(!name)continue;result.push(name+(item&&item.kind?' · '+cleanText(item.kind):'')+(item&&item.detail?' · '+cleanText(item.detail):''))}return result}
function orderLines(briefing){const data=briefing||{};const characters=characterSummaryLines(data);const dedication=(cleanText(data.dedicationTitle)?cleanText(data.dedicationTitle)+' · ':'')+(cleanText(data.dedication)||'sem dedicatória');return [['Criança',cleanText(data.name)],['Faixa etária',cleanText(data.age)+(data.years===''||data.years===undefined||data.years===null?'':' · '+data.years+' anos')],['Tema',cleanText(data.theme)],['Sentimento',cleanText(data.feeling)],['Estilo',cleanText(data.style)],['Objetivo',cleanText(data.objective)],['Personagens que vão aparecer',characters.join(' | ')],['Idioma','Português (BR)'],['Personagem principal',cleanText(data.gender)+(cleanText(data.personality)?' · '+cleanText(data.personality):'')],['Roupa',data.outfit==='original'?'manter a da foto':'roupa nova da aventura'],['Dedicatória',dedication],['Detalhes',cleanText(data.details)||'nenhum'],['WhatsApp do cliente',cleanText(data.whatsapp)]]}
function orderSummary(briefing,code,settings,link){const body=orderLines(briefing).filter(entry=>cleanText(entry[1])).map(entry=>'• '+entry[0]+': '+entry[1]);return ['*Pedido '+code+'* — '+settings.shop,'',...body,'','*Valor:* '+settings.price+(settings.pix?' · Pix: '+settings.pix:''),'*Pagamento:* '+(settings.pixCopyPaste?'Pix disponível para pagamento imediato.':'combinado por aqui, no WhatsApp.'),'','📷 A foto escolhida e todos os dados estão neste link:','🔗 '+(link||orderLink(code,''))].join('\n')}
function orderLink(code,token){return '/pedido/'+encodeURIComponent(code)+(token?'?t='+encodeURIComponent(token):'')}
function orderWhatsAppLink(settings,summary){return settings.whatsapp?'https://wa.me/'+settings.whatsapp+'?text='+encodeURIComponent(summary):''}
function customerWhatsAppLink(briefing){let number=cleanText(briefing&&briefing.whatsapp).replace(/[^0-9]/g,'');if((number.length===10||number.length===11)&&!number.startsWith('55'))number='55'+number;return number?'https://wa.me/'+number:''}
function visitDayKey(){return new Date(Date.now()-3*60*60*1000).toISOString().slice(0,10)}
async function visitStats(env){if(!env||!env.BUCKET)return {total:0,today:0};const object=await env.BUCKET.get('analytics/visits.json');if(!object)return {total:0,today:0};try{const data=await object.json();const days=data&&data.days&&typeof data.days==='object'?data.days:{};return {total:Number(data&&data.total)||0,today:Number(days[visitDayKey()])||0}}catch{return {total:0,today:0}}}
async function registerVisit(env,sessionToken){if(!env||!env.BUCKET||!sessionToken)return visitStats(env);const marker='analytics/visit-sessions/'+sessionToken+'.json';if(await env.BUCKET.get(marker))return visitStats(env);const object=await env.BUCKET.get('analytics/visits.json');let data={total:0,days:{}};if(object){try{const parsed=await object.json();if(parsed&&typeof parsed==='object')data={total:Number(parsed.total)||0,days:parsed.days&&typeof parsed.days==='object'?parsed.days:{}}}catch{}}const day=visitDayKey();data.total+=1;data.days[day]=(Number(data.days[day])||0)+1;const keys=Object.keys(data.days).sort();for(const key of keys.slice(0,Math.max(0,keys.length-90)))delete data.days[key];await env.BUCKET.put('analytics/visits.json',JSON.stringify(data),{httpMetadata:{contentType:'application/json'}});await env.BUCKET.put(marker,JSON.stringify({at:new Date().toISOString()}),{httpMetadata:{contentType:'application/json'}});return {total:data.total,today:data.days[day]||0}}
async function funnelStats(env){if(!env||!env.BUCKET)return {steps:[0,0,0,0,0],orders:0};const object=await env.BUCKET.get('analytics/funnel.json');if(!object)return {steps:[0,0,0,0,0],orders:0};try{const data=await object.json();const steps=Array.from({length:5},(_,i)=>Number(data&&data.steps&&data.steps[i])||0);return {steps,orders:Number(data&&data.orders)||0}}catch{return {steps:[0,0,0,0,0],orders:0}}}
async function registerFunnelStep(env,sessionToken,step){if(!env||!env.BUCKET||!sessionToken)return funnelStats(env);const current=Math.max(0,Math.min(4,Number(step)||0));const markerKey='analytics/funnel-sessions/'+sessionToken+'.json';const markerObject=await env.BUCKET.get(markerKey);let marker={maxStep:-1,ordered:false};if(markerObject){try{const saved=await markerObject.json();marker={maxStep:Number.isFinite(Number(saved&&saved.maxStep))?Number(saved.maxStep):-1,ordered:Boolean(saved&&saved.ordered)}}catch{}}if(current<=marker.maxStep)return funnelStats(env);const stats=await funnelStats(env);for(let i=Math.max(0,marker.maxStep+1);i<=current;i++)stats.steps[i]=(Number(stats.steps[i])||0)+1;marker.maxStep=current;await env.BUCKET.put('analytics/funnel.json',JSON.stringify(stats),{httpMetadata:{contentType:'application/json'}});await env.BUCKET.put(markerKey,JSON.stringify(marker),{httpMetadata:{contentType:'application/json'}});return stats}
async function registerFunnelOrder(env,sessionToken){if(!env||!env.BUCKET||!sessionToken)return funnelStats(env);await registerFunnelStep(env,sessionToken,4);const markerKey='analytics/funnel-sessions/'+sessionToken+'.json';const markerObject=await env.BUCKET.get(markerKey);let marker={maxStep:4,ordered:false};if(markerObject){try{const saved=await markerObject.json();marker={maxStep:Math.max(4,Number(saved&&saved.maxStep)||0),ordered:Boolean(saved&&saved.ordered)}}catch{}}if(marker.ordered)return funnelStats(env);const stats=await funnelStats(env);stats.orders=(Number(stats.orders)||0)+1;marker.ordered=true;await env.BUCKET.put('analytics/funnel.json',JSON.stringify(stats),{httpMetadata:{contentType:'application/json'}});await env.BUCKET.put(markerKey,JSON.stringify(marker),{httpMetadata:{contentType:'application/json'}});return stats}
async function orderIndex(env){const object=await env.BUCKET.get('orders/index.json');if(!object)return [];try{const list=await object.json();return Array.isArray(list)?list:[]}catch{return []}}
async function draftIndex(env){const object=await env.BUCKET.get('briefings/index.json');if(!object)return [];try{const list=await object.json();return Array.isArray(list)?list:[]}catch{return []}}
async function quizPreviewIndex(env){if(!env||!env.BUCKET)return [];const object=await env.BUCKET.get('quiz-previews/index.json');if(!object)return [];try{const list=await object.json();return Array.isArray(list)?list:[]}catch{return []}}
async function saveQuizPreviewRecord(env,record){if(!env||!env.BUCKET)return null;const now=new Date().toISOString();const id=orderCleanCode(record&&record.id)||orderCode();const saved={id,createdAt:record&&record.createdAt?record.createdAt:now,sessionToken:cleanText(record&&record.sessionToken).slice(0,64),type:cleanText(record&&record.type).slice(0,60),style:cleanText(record&&record.style).slice(0,100),model:cleanText(record&&record.model).slice(0,100),provider:cleanText(record&&record.provider).slice(0,40)||'quackapi',original:cleanText(record&&record.original),preview:cleanText(record&&record.preview),revisedPrompt:cleanText(record&&record.revisedPrompt).slice(0,4000),status:cleanText(record&&record.status).slice(0,30)||'gerada'};await env.BUCKET.put('quiz-previews/'+id+'.json',JSON.stringify(saved),{httpMetadata:{contentType:'application/json'}});const list=await quizPreviewIndex(env);const item={id:saved.id,createdAt:saved.createdAt,type:saved.type,style:saved.style,model:saved.model,provider:saved.provider,status:saved.status,hasOriginal:Boolean(saved.original),hasPreview:Boolean(saved.preview)};const next=[item,...list.filter(entry=>entry&&entry.id!==id)].slice(0,500);await env.BUCKET.put('quiz-previews/index.json',JSON.stringify(next),{httpMetadata:{contentType:'application/json'}});return item}
async function readQuizPreviewRecord(env,id){const clean=orderCleanCode(id);if(!clean||!env||!env.BUCKET)return null;const object=await env.BUCKET.get('quiz-previews/'+clean+'.json');if(!object)return null;try{return await object.json()}catch{return null}}
async function deleteQuizPreviewRecord(env,id){const clean=orderCleanCode(id);if(!clean||!env||!env.BUCKET)return false;const existing=await env.BUCKET.get('quiz-previews/'+clean+'.json');if(!existing)return false;if(typeof env.BUCKET.delete==='function')await env.BUCKET.delete('quiz-previews/'+clean+'.json');const list=await quizPreviewIndex(env);await env.BUCKET.put('quiz-previews/index.json',JSON.stringify(list.filter(item=>item&&item.id!==clean)),{httpMetadata:{contentType:'application/json'}});return true}
async function saveDraftIndex(env,sessionToken,body){const now=new Date().toISOString();const data=(body&&body.data)||{};const list=await draftIndex(env);const previous=list.find(item=>item&&item.token===sessionToken);const step=Math.max(0,Math.min(4,Number(body&&body.step)||0));const item={token:sessionToken,cartId:sessionToken.slice(0,10).toUpperCase(),createdAt:previous&&previous.createdAt?previous.createdAt:now,updatedAt:now,step,progress:Math.round((step+1)/5*100),name:cleanText(data.name),whatsapp:cleanText(data.whatsapp),theme:cleanText(data.theme),hasPhoto:Boolean(data.photo)};const next=[item,...list.filter(entry=>entry&&entry.token!==sessionToken)].slice(0,500);await env.BUCKET.put('briefings/index.json',JSON.stringify(next),{httpMetadata:{contentType:'application/json'}});return item}
async function removeDraftIndex(env,sessionToken){const list=await draftIndex(env);await env.BUCKET.put('briefings/index.json',JSON.stringify(list.filter(item=>item&&item.token!==sessionToken)),{httpMetadata:{contentType:'application/json'}})}
function recoveryWhatsAppLink(cart,settings){const link=customerWhatsAppLink({whatsapp:cart&&cart.whatsapp});if(!link)return '';const name=cleanText(cart&&cart.name);const message='Olá'+(name?', '+name:'')+'! Você começou a criar um livro personalizado na '+settings.shop+' e o pedido não foi finalizado. Se quiser, posso te ajudar a concluir de onde você parou.';return link+'?text='+encodeURIComponent(message)}
function minutesSince(value){const time=new Date(value||0).getTime();if(!Number.isFinite(time))return 0;return Math.max(0,Math.floor((Date.now()-time)/60000))}

async function saveOrderRecord(env,record){await env.BUCKET.put('orders/'+record.code+'.json',JSON.stringify(record),{httpMetadata:{contentType:'application/json'}});const list=await orderIndex(env);list.unshift({code:record.code,accessToken:record.accessToken,createdAt:record.createdAt,name:record.briefing.name,whatsapp:cleanText(record.briefing.whatsapp),theme:cleanText(record.briefing.theme),hasPhoto:Boolean(record.briefing.photo),status:record.status,total:record.total});await env.BUCKET.put('orders/index.json',JSON.stringify(list.slice(0,500)),{httpMetadata:{contentType:'application/json'}});return record}
async function readOrderRecord(env,code){const clean=orderCleanCode(code);if(!clean)return null;const object=await env.BUCKET.get('orders/'+clean+'.json');if(!object)return null;return object.json()}
async function deleteOrderRecord(env,code){const clean=orderCleanCode(code);if(!clean)return false;const existing=await env.BUCKET.get('orders/'+clean+'.json');if(!existing)return false;if(typeof env.BUCKET.delete==='function')await env.BUCKET.delete('orders/'+clean+'.json');const list=await orderIndex(env);await env.BUCKET.put('orders/index.json',JSON.stringify(list.filter(item=>item&&item.code!==clean)),{httpMetadata:{contentType:'application/json'}});return true}
async function updateOrderStatus(env,code,status){const clean=orderCleanCode(code);const next=cleanText(status).toLowerCase();if(!clean||!ORDER_STATUSES.includes(next))return null;const record=await readOrderRecord(env,clean);if(!record)return null;record.status=next;record.updatedAt=new Date().toISOString();await env.BUCKET.put('orders/'+clean+'.json',JSON.stringify(record),{httpMetadata:{contentType:'application/json'}});const list=await orderIndex(env);const updated=list.map(item=>item&&item.code===clean?{...item,status:next,updatedAt:record.updatedAt}:item);await env.BUCKET.put('orders/index.json',JSON.stringify(updated),{httpMetadata:{contentType:'application/json'}});return record}
async function uploadWhatsAppMedia(settings,jpegBytes){const form=new FormData();form.append('messaging_product','whatsapp');form.append('type','image/jpeg');form.append('file',new Blob([jpegBytes],{type:'image/jpeg'}),'foto-referencia.jpg');const response=await fetch('https://graph.facebook.com/v21.0/'+settings.phoneId+'/media',{method:'POST',headers:{authorization:'Bearer '+settings.token},body:form});if(!response.ok)throw new Error('WhatsApp recusou a imagem ('+response.status+')');const data=await response.json();return data.id}
async function sendOrderToWhatsApp(settings,summary,briefing){if(!settings.token||!settings.phoneId||!settings.whatsapp)return {sent:false,reason:'Envio automático desligado'};const endpoint='https://graph.facebook.com/v21.0/'+settings.phoneId+'/messages';const headers={'content-type':'application/json',authorization:'Bearer '+settings.token};const photos=[];if(briefing&&briefing.photo)photos.push({name:cleanText(briefing.name)||'Personagem principal',photo:briefing.photo});for(const item of (Array.isArray(briefing&&briefing.cast)?briefing.cast:[])){if(item&&item.photo)photos.push({name:cleanText(item.name)||'Personagem',photo:item.photo})}for(const item of photos){const jpeg=pdfJpegBytes(item.photo);if(!jpeg)continue;const mediaId=await uploadWhatsAppMedia(settings,jpeg);const uploaded=await fetch(endpoint,{method:'POST',headers,body:JSON.stringify({messaging_product:'whatsapp',to:settings.whatsapp,type:'image',image:{id:mediaId,caption:'Referência — '+item.name}})});if(!uploaded.ok)throw new Error('WhatsApp recusou a foto ('+uploaded.status+')')}const response=await fetch(endpoint,{method:'POST',headers,body:JSON.stringify({messaging_product:'whatsapp',to:settings.whatsapp,type:'text',text:{preview_url:true,body:summary.slice(0,4000)}})});if(!response.ok)throw new Error('WhatsApp recusou a mensagem ('+response.status+')');return {sent:true,reason:''}}
const ORDER_CSS=':root{font-family:system-ui,sans-serif;color:#252039;background:#faf9ff;font-size:16px;--violet:#7344d6;--line:#e7e2f2}body{margin:0;padding:18px 16px 40px;max-width:640px;margin:0 auto}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:28px 0 10px}.code{font-size:13px;color:#6b5f7d}.badge{display:inline-block;background:#f0eafb;color:#5b3fa8;border-radius:99px;padding:4px 12px;font-size:12px;font-weight:700;text-transform:uppercase}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:16px 18px;margin:14px 0}.photo{width:100%;max-width:260px;border-radius:16px;display:block;margin:0 auto 6px}dl{display:grid;grid-template-columns:118px 1fr;gap:10px;font-size:14px;margin:0}dt{color:#897b96}dd{margin:0;overflow-wrap:anywhere}pre{white-space:pre-wrap;font:13px/1.5 ui-monospace,monospace;margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.primary,.secondary{display:inline-block;text-decoration:none;border-radius:12px;padding:13px 18px;font-weight:700;font-size:15px;border:0;cursor:pointer}.primary{background:var(--violet);color:white}.secondary{background:white;color:#665974;border:1px solid var(--line)}.pix{background:#fff8e6;border:1px solid #f2dfae;border-radius:12px;padding:12px;font-weight:700;word-break:break-all}.note{font-size:12px;color:#7d7089}.table{width:100%;border-collapse:collapse;font-size:14px}.table th,.table td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line)}.table a{color:var(--violet);font-weight:700;text-decoration:none}.empty{color:#7c6b8b;padding:20px 0}';
const ADMIN_CSS='.admin-body{max-width:none;padding:0;background:#f5f6fa;color:#1f2430}.admin-topbar{background:#111827;color:#fff;padding:18px 28px;display:flex;align-items:center;justify-content:space-between;gap:18px;position:sticky;top:0;z-index:20;box-shadow:0 1px 0 rgba(255,255,255,.06)}.admin-brand{display:flex;align-items:center;gap:12px;font-weight:800}.admin-logo{width:38px;height:38px;border-radius:11px;background:linear-gradient(135deg,#7c3aed,#4f46e5);display:grid;place-items:center;font-weight:900}.admin-topmeta{font-size:12px;color:#cbd5e1;text-align:right}.admin-shell{max-width:1440px;margin:0 auto;padding:28px}.admin-heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:22px}.admin-heading h1{font-size:28px;letter-spacing:-.6px}.admin-heading p{margin:6px 0 0}.storage-ok,.storage-warn{display:inline-flex;align-items:center;gap:7px;border-radius:999px;padding:8px 12px;font-size:12px;font-weight:800}.storage-ok{background:#ecfdf5;color:#047857}.storage-warn{background:#fff1f2;color:#be123c}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:14px;margin:22px 0}.metric{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:18px;box-shadow:0 1px 2px rgba(15,23,42,.04)}.metric span{display:block;color:#6b7280;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.6px}.metric strong{display:block;font-size:30px;margin-top:8px;letter-spacing:-1px}.admin-toolbar{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:14px;display:grid;grid-template-columns:minmax(220px,1fr) 210px auto;gap:12px;align-items:center}.admin-input,.admin-select{width:100%;border:1px solid #d7dce5;border-radius:11px;padding:11px 12px;background:#fff}.admin-count{font-size:13px;color:#6b7280;white-space:nowrap}.admin-table-card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;margin-top:14px;overflow:auto;box-shadow:0 1px 2px rgba(15,23,42,.04)}.admin-table{width:100%;border-collapse:collapse;min-width:1000px}.admin-table th{text-align:left;padding:12px 14px;background:#f9fafb;color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:.6px;border-bottom:1px solid #e5e7eb}.admin-table td{padding:14px;border-bottom:1px solid #eef0f4;font-size:13px;vertical-align:middle}.admin-table tr:hover td{background:#fafaff}.order-link{font-weight:850;color:#5b21b6;text-decoration:none}.client-name{font-weight:800}.muted{color:#6b7280}.wa-link{color:#047857;text-decoration:none;font-weight:750}.status-pill{display:inline-flex;border-radius:999px;padding:6px 9px;font-size:11px;font-weight:850;text-transform:uppercase;letter-spacing:.3px}.status-novo{background:#eef2ff;color:#4338ca}.status-em-producao{background:#fff7ed;color:#c2410c}.status-pago{background:#ecfdf5;color:#047857}.status-enviado{background:#eff6ff;color:#1d4ed8}.status-cancelado{background:#fff1f2;color:#be123c}.row-actions{display:flex;gap:7px}.mini-btn{border:1px solid #d9dde5;background:#fff;border-radius:9px;padding:7px 9px;text-decoration:none;color:#374151;font-weight:750;font-size:12px}.mini-btn.danger{color:#b91c1c;border-color:#fecaca}.admin-empty{padding:44px;text-align:center;color:#6b7280}.admin-order-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.status-box{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:14px;min-width:270px}.status-box label{font-size:12px;color:#6b7280;font-weight:800;display:block;margin-bottom:7px}.status-row{display:flex;gap:8px}.status-row select{flex:1;border:1px solid #d7dce5;border-radius:9px;padding:9px}.status-row button{border:0;background:#111827;color:#fff;border-radius:9px;padding:9px 12px;font-weight:800}.admin-back{display:inline-flex;margin-bottom:14px;color:#5b21b6;text-decoration:none;font-weight:800}.photo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.photo-grid .card{margin:0}.admin-section{margin-top:28px}.admin-section h2{font-size:18px}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-toolbar{grid-template-columns:1fr 180px}.admin-count{grid-column:1/-1}}@media(max-width:640px){.admin-shell{padding:18px 12px}.admin-topbar{padding:14px 16px}.admin-topmeta{display:none}.admin-heading{display:block}.metrics{grid-template-columns:1fr 1fr}.metric strong{font-size:24px}.admin-toolbar{grid-template-columns:1fr}.admin-count{grid-column:auto}.admin-order-head{display:block}.status-box{margin-top:14px;min-width:0}}.admin-layout{display:grid;grid-template-columns:248px minmax(0,1fr);min-height:100vh}.admin-sidebar{background:#0f172a;color:#fff;padding:20px 14px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column;gap:22px}.side-brand{display:flex;gap:11px;align-items:center;padding:0 8px}.side-brand .admin-logo{flex:0 0 auto}.side-brand small{display:block;color:#94a3b8;margin-top:2px}.admin-nav{display:grid;gap:6px}.admin-nav a{color:#cbd5e1;text-decoration:none;padding:11px 12px;border-radius:10px;font-weight:700;font-size:14px;display:flex;align-items:center;gap:10px}.admin-nav a:hover,.admin-nav a.active{background:#1e293b;color:#fff}.admin-side-foot{margin-top:auto;padding:12px 8px;color:#94a3b8;font-size:12px;line-height:1.5}.admin-main{min-width:0}.settings-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);gap:18px}.settings-card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:20px;box-shadow:0 1px 2px rgba(15,23,42,.04)}.settings-card h2{font-size:17px;margin:0 0 5px}.settings-card>p{font-size:13px;margin:0 0 18px}.settings-form{display:grid;gap:14px}.settings-form label{font-size:12px;font-weight:800;color:#4b5563;margin:0}.settings-form input{margin-top:6px;width:100%;border:1px solid #d7dce5;border-radius:10px;padding:11px 12px}.settings-actions{display:flex;gap:10px;align-items:center;margin-top:4px}.settings-save{border:0;background:#111827;color:#fff;border-radius:10px;padding:11px 16px;font-weight:800}.integration-list{display:grid;gap:10px}.integration{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;border:1px solid #e5e7eb;border-radius:12px;padding:13px}.integration strong{font-size:14px}.integration small{display:block;color:#6b7280;margin-top:3px;line-height:1.4}.signal{font-size:11px;font-weight:850;border-radius:999px;padding:6px 8px;white-space:nowrap}.signal.ok{background:#ecfdf5;color:#047857}.signal.warn{background:#fff7ed;color:#c2410c}.signal.off{background:#f3f4f6;color:#6b7280}.settings-note{border-radius:12px;padding:13px;background:#f8fafc;color:#475569;font-size:12px;line-height:1.5}.settings-note.warn{background:#fff7ed;color:#9a3412}.quick-links{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.quick-link{border:1px solid #e5e7eb;border-radius:12px;padding:14px;text-decoration:none;color:#111827;font-weight:800;background:#fff}.quick-link small{display:block;color:#6b7280;font-weight:500;margin-top:4px}@media(max-width:900px){.admin-layout{grid-template-columns:1fr}.admin-sidebar{position:relative;height:auto;display:block}.admin-nav{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:14px}.admin-side-foot{display:none}.settings-grid{grid-template-columns:1fr}}@media(max-width:560px){.admin-nav{grid-template-columns:1fr 1fr}.quick-links{grid-template-columns:1fr}}';
const ADMIN_CART_CSS='.cart-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-end;margin-top:30px}.cart-head h2{font-size:20px;margin:0}.cart-head p{margin:5px 0 0}.cart-progress{height:7px;background:#e5e7eb;border-radius:99px;overflow:hidden;min-width:110px}.cart-progress span{display:block;height:100%;background:#7c3aed}.cart-age{font-size:12px;color:#6b7280}.cart-recover{background:#ecfdf5!important;color:#047857!important;border-color:#a7f3d0!important}.cart-alert{background:#fff7ed;border:1px solid #fed7aa;border-radius:14px;padding:14px;color:#9a3412;font-size:13px;margin:12px 0 0}@media(max-width:640px){.cart-head{display:block}.cart-head .admin-count{margin-top:8px}}.funnel-wrap{margin:26px 0}.funnel-card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:20px}.funnel-card h2{font-size:20px;margin:0 0 5px}.funnel-card>p{margin:0 0 18px}.funnel-list{display:grid;gap:12px}.funnel-row{display:grid;grid-template-columns:170px 1fr 86px;gap:14px;align-items:center}.funnel-name strong{display:block;font-size:14px}.funnel-name small{display:block;color:#6b7280;margin-top:2px}.funnel-track{height:12px;background:#eef0f4;border-radius:999px;overflow:hidden}.funnel-fill{height:100%;background:#7c3aed;border-radius:999px;min-width:2px}.funnel-value{text-align:right;font-weight:850}.funnel-value small{display:block;color:#6b7280;font-weight:600}.funnel-insight{margin-top:16px;padding:13px 14px;border-radius:12px;background:#f8fafc;color:#475569;font-size:13px}.funnel-insight strong{color:#111827}@media(max-width:640px){.funnel-row{grid-template-columns:1fr}.funnel-value{text-align:left}.funnel-track{order:3}}';
function adminNavHtml(settings,adminToken,active){const base='/painel?token='+encodeURIComponent(adminToken);return '<aside class="admin-sidebar"><div class="side-brand"><div class="admin-logo">FC</div><div><strong>FC Livros Mágicos</strong><small>Painel administrativo</small></div></div><nav class="admin-nav"><a class="'+(active==='dashboard'?'active':'')+'" href="'+base+'">▦ Dashboard</a><a class="'+(active==='orders'?'active':'')+'" href="'+base+'#pedidos">☰ Pedidos</a><a class="'+(active==='previews'?'active':'')+'" href="'+base+'&view=previews">🖼 Prévias IA</a><a href="'+base+'#carrinhos">↩ Carrinhos</a><a class="'+(active==='settings'?'active':'')+'" href="'+base+'&view=config">⚙ Configurações</a><a href="/quiz" target="_blank" rel="noopener">↗ Abrir quiz</a><a href="/" target="_blank" rel="noopener">↗ Abrir site</a></nav><div class="admin-side-foot">'+escapeHtml(settings.shop)+'<br>Área protegida por ADMIN_TOKEN</div></aside>'}
function adminLayoutHtml(content,settings,adminToken,active,title,script){return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+escapeHtml(title)+' — '+escapeHtml(settings.shop)+'</title><style>'+ORDER_CSS+ADMIN_CSS+ADMIN_CART_CSS+ADMIN_PREVIEW_CSS+'</style></head><body class="admin-body"><div class="admin-layout">'+adminNavHtml(settings,adminToken,active)+'<div class="admin-main"><header class="admin-topbar"><div><strong>'+escapeHtml(title)+'</strong></div><div class="admin-topmeta">'+(settings.whatsapp?'WhatsApp: '+escapeHtml(settings.whatsapp):'WhatsApp não configurado')+' · '+escapeHtml(settings.price)+'</div></header><main class="admin-shell">'+content+'</main></div></div>'+(script||'')+'</body></html>'}
const ADMIN_PREVIEW_CSS='.preview-admin-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:16px;margin-top:18px}.preview-admin-card{background:#fff;border:1px solid #e5e7eb;border-radius:17px;overflow:hidden;box-shadow:0 1px 2px rgba(15,23,42,.04)}.preview-admin-images{display:grid;grid-template-columns:1fr 1fr;background:#111827;min-height:180px}.preview-admin-image{position:relative;min-width:0}.preview-admin-image img{width:100%;height:220px;object-fit:cover;display:block;background:#111}.preview-admin-label{position:absolute;left:8px;bottom:8px;background:rgba(15,23,42,.82);color:#fff;border-radius:999px;padding:5px 8px;font-size:10px;font-weight:850}.preview-admin-body{padding:15px}.preview-admin-title{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.preview-admin-title strong{font-size:15px}.preview-admin-meta{display:grid;gap:5px;margin:10px 0 13px;color:#6b7280;font-size:12px}.preview-admin-actions{display:flex;gap:8px;flex-wrap:wrap}.preview-admin-actions a{flex:1;text-align:center}.preview-empty{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:42px;text-align:center;color:#6b7280}@media(max-width:560px){.preview-admin-images{grid-template-columns:1fr}.preview-admin-image img{height:260px}}';
function previewAdminHtml(list,settings,adminToken){const safe=(Array.isArray(list)?list:[]).filter(Boolean);const cards=safe.map(item=>{const q='?token='+encodeURIComponent(adminToken)+'&id='+encodeURIComponent(item.id);const original='/api/admin/preview-image'+q+'&kind=original';const preview='/api/admin/preview-image'+q+'&kind=preview';return '<article class="preview-admin-card"><div class="preview-admin-images">'+(item.hasOriginal?'<div class="preview-admin-image"><img loading="lazy" src="'+original+'" alt="Foto original"><span class="preview-admin-label">ORIGINAL</span></div>':'')+(item.hasPreview?'<div class="preview-admin-image"><img loading="lazy" src="'+preview+'" alt="Prévia gerada"><span class="preview-admin-label">GERADA</span></div>':'')+'</div><div class="preview-admin-body"><div class="preview-admin-title"><strong>#'+escapeHtml(item.id)+'</strong><span class="status-pill status-enviado">'+escapeHtml(item.status||'gerada')+'</span></div><div class="preview-admin-meta"><span><strong>Tipo:</strong> '+escapeHtml(item.type||'—')+'</span><span><strong>Estilo:</strong> '+escapeHtml(item.style||'—')+'</span><span><strong>Modelo:</strong> '+escapeHtml(item.model||'—')+'</span><span><strong>Data:</strong> '+escapeHtml(new Date(item.createdAt).toLocaleString('pt-BR'))+'</span></div><div class="preview-admin-actions">'+(item.hasOriginal?'<a class="mini-btn" target="_blank" href="'+original+'">Original</a>':'')+(item.hasPreview?'<a class="mini-btn" target="_blank" href="'+preview+'">Prévia</a>':'')+'<a class="mini-btn danger" href="/painel?token='+encodeURIComponent(adminToken)+'&view=previews&apagarPreview='+encodeURIComponent(item.id)+'" onclick="return confirm(\'Apagar esta geração e as duas imagens?\')">Apagar</a></div></div></article>'}).join('');const content='<div class="admin-heading"><div><h1>Prévias geradas por IA</h1><p>Fotos enviadas no quiz e resultados produzidos pela QuackAPI.</p></div><div>'+(settings.storagePersistent?'<span class="storage-ok">● Salvas no Vercel Blob</span>':'<span class="storage-warn">● Armazenamento temporário</span>')+'</div></div><section class="metrics"><div class="metric"><span>Prévias salvas</span><strong>'+safe.length+'</strong></div><div class="metric"><span>Com original</span><strong>'+safe.filter(x=>x.hasOriginal).length+'</strong></div><div class="metric"><span>Com resultado</span><strong>'+safe.filter(x=>x.hasPreview).length+'</strong></div></section>'+(cards?'<section class="preview-admin-grid">'+cards+'</section>':'<div class="preview-empty"><strong>Nenhuma prévia salva ainda.</strong><br>As próximas gerações do quiz aparecerão aqui automaticamente.</div>');return adminLayoutHtml(content,settings,adminToken,'previews','Prévias IA')}
function adminSettingsHtml(settings,adminToken,info){const persistent=Boolean(settings.storagePersistent);const cloudWa=Boolean(settings.token&&settings.phoneId&&settings.whatsapp);const ai=Boolean(info&&info.aiConfigured);const form='<section class="settings-card"><h2>Dados da loja</h2><p>Altere as informações usadas nos pedidos e no contato com clientes.</p><form class="settings-form" id="admin-settings-form"><label>Nome da loja<input name="shop" maxlength="80" value="'+escapeHtml(settings.shop)+'"></label><label>WhatsApp da loja<input name="whatsapp" maxlength="20" inputmode="tel" value="'+escapeHtml(settings.whatsapp)+'" placeholder="5585999999999"></label><label>Preço do livro<input name="price" maxlength="40" value="'+escapeHtml(settings.price)+'" placeholder="R$ 49,90"></label><label>Chave Pix<input name="pix" maxlength="160" value="'+escapeHtml(settings.pix)+'" placeholder="CPF, telefone, e-mail ou chave aleatória"></label><label>Pix Copia e Cola<textarea name="pixCopyPaste" maxlength="1200" placeholder="Cole aqui o código Pix Copia e Cola gerado pelo seu banco">'+escapeHtml(settings.pixCopyPaste||'')+'</textarea><small class="note">O cliente poderá copiar este código e pagar imediatamente no app do banco.</small></label><div class="settings-actions"><button class="settings-save" type="submit">Salvar configurações</button><span class="note" id="settings-status"></span></div></form>'+(persistent?'':'<div class="settings-note warn" style="margin-top:16px"><strong>Atenção:</strong> o Vercel Blob ainda não está conectado. Alterações feitas aqui podem desaparecer após uma reinicialização ou novo deploy.</div>')+'</section>';const integrations='<section class="settings-card"><h2>Integrações e segurança</h2><p>Visão geral das conexões do sistema. Segredos nunca são exibidos.</p><div class="integration-list"><div class="integration"><div><strong>Armazenamento persistente</strong><small>Guarda pedidos, briefings, fotos e configurações.</small></div><span class="signal '+(persistent?'ok':'warn')+'">'+(persistent?'ATIVO':'PENDENTE')+'</span></div><div class="integration"><div><strong>Proteção do administrador</strong><small>Acesso ao painel protegido por token privado.</small></div><span class="signal '+(settings.admin?'ok':'off')+'">'+(settings.admin?'ATIVA':'INATIVA')+'</span></div><div class="integration"><div><strong>WhatsApp da loja</strong><small>Número usado para receber e responder pedidos.</small></div><span class="signal '+(settings.whatsapp?'ok':'off')+'">'+(settings.whatsapp?'ATIVO':'INATIVO')+'</span></div><div class="integration"><div><strong>WhatsApp Cloud API</strong><small>Envio automático pelo servidor, sem abrir o WhatsApp manualmente.</small></div><span class="signal '+(cloudWa?'ok':'off')+'">'+(cloudWa?'ATIVA':'NÃO CONFIGURADA')+'</span></div><div class="integration"><div><strong>IA para histórias</strong><small>Geração automática de história e prompts de ilustração.</small></div><span class="signal '+(ai?'ok':'warn')+'">'+(ai?'CONFIGURADA':'DEMONSTRAÇÃO')+'</span></div></div></section>';const links='<section class="settings-card"><h2>Acessos rápidos</h2><p>Atalhos para as áreas usadas no dia a dia.</p><div class="quick-links"><a class="quick-link" href="/painel?token='+encodeURIComponent(adminToken)+'">Dashboard<small>Pedidos e indicadores</small></a><a class="quick-link" href="/" target="_blank" rel="noopener">Site público<small>Abrir formulário do cliente</small></a></div></section>';const security='<section class="settings-card"><h2>Segurança</h2><p>Configurações sensíveis continuam na Vercel e não aparecem no painel.</p><div class="settings-note"><strong>ADMIN_TOKEN</strong>, <strong>ORDER_SECRET</strong>, tokens da WhatsApp Cloud API e chaves de IA não são mostrados ou salvos pelo formulário desta página.</div></section>';const script='<script>(function(){var form=document.getElementById("admin-settings-form"),status=document.getElementById("settings-status");form.addEventListener("submit",function(e){e.preventDefault();var button=form.querySelector("button");button.disabled=true;status.textContent="Salvando…";var body={};new FormData(form).forEach(function(v,k){body[k]=v});fetch("/api/admin/settings?token='+encodeURIComponent(adminToken)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)}).then(function(r){return r.json().then(function(j){return {ok:r.ok,data:j}})}).then(function(result){button.disabled=false;if(result.ok){status.textContent="Configurações salvas.";setTimeout(function(){window.location.reload()},500)}else status.textContent=result.data&&result.data.error?result.data.error:"Não foi possível salvar."}).catch(function(){button.disabled=false;status.textContent="Não foi possível salvar."})})})()</script>';return adminLayoutHtml('<div class="admin-heading"><div><h1>Configurações</h1><p>Controle os dados comerciais e acompanhe a saúde das integrações.</p></div></div><div class="settings-grid"><div>'+form+'<div style="height:18px"></div>'+links+'</div><div>'+integrations+'<div style="height:18px"></div>'+security+'</div></div>',settings,adminToken,'settings','Configurações',script)}
function painelHtml(list,settings,adminToken,origin,drafts,analytics,funnel){const safeList=(Array.isArray(list)?list:[]).filter(Boolean);const safeDrafts=(Array.isArray(drafts)?drafts:[]).filter(Boolean);const abandoned=safeDrafts.filter(item=>minutesSince(item.updatedAt)>=30).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));const visitData=analytics||{total:0,today:0};const counts={total:safeList.length,novo:0,producao:0,pago:0,enviado:0,abandonados:abandoned.length,visitas:Number(visitData.total)||0,hoje:Number(visitData.today)||0};for(const item of safeList){if(item.status==='novo')counts.novo++;else if(item.status==='em produção')counts.producao++;else if(item.status==='pago')counts.pago++;else if(item.status==='enviado')counts.enviado++}const funnelData=funnel||{steps:[0,0,0,0,0],orders:0};const funnelLabels=['A criança','A história','Personagens','Personalização','Finalizar','Pedido enviado'];const funnelValues=[...(Array.isArray(funnelData.steps)?funnelData.steps.slice(0,5):[0,0,0,0,0]),Number(funnelData.orders)||0].map(value=>Number(value)||0);while(funnelValues.length<6)funnelValues.push(0);const funnelBase=Math.max(1,funnelValues[0]||0);const funnelRows=funnelLabels.map((label,index)=>{const value=funnelValues[index];const pct=Math.round(value/funnelBase*100);const previous=index===0?value:funnelValues[index-1];const advance=index===0?100:(previous?Math.round(value/previous*100):0);return '<div class="funnel-row"><div class="funnel-name"><strong>'+escapeHtml(label)+'</strong><small>'+(index===0?'entrada no funil':advance+'% avançaram da etapa anterior')+'</small></div><div class="funnel-track"><div class="funnel-fill" style="width:'+Math.max(0,Math.min(100,pct))+'%"></div></div><div class="funnel-value">'+value+'<small>'+pct+'%</small></div></div>'}).join('');let biggestDrop={from:'',to:'',drop:-1};for(let i=1;i<funnelValues.length;i++){const prev=funnelValues[i-1],curr=funnelValues[i];if(prev>0){const drop=Math.max(0,Math.round((prev-curr)/prev*100));if(drop>biggestDrop.drop)biggestDrop={from:funnelLabels[i-1],to:funnelLabels[i],drop}}}const funnelInsight=biggestDrop.drop>=0?'<div class="funnel-insight"><strong>Maior queda:</strong> '+escapeHtml(biggestDrop.from)+' → '+escapeHtml(biggestDrop.to)+' · '+biggestDrop.drop+'% não avançaram.</div>':'<div class="funnel-insight">Os dados do funil começam a aparecer conforme novas pessoas avançarem pelo formulário.</div>';const funnelSection='<section class="funnel-wrap"><div class="funnel-card"><h2>Funil de conversão</h2><p>Veja até onde as pessoas estão indo no formulário e onde mais desistem.</p><div class="funnel-list">'+funnelRows+'</div>'+funnelInsight+'</div></section>';const statusSlug=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'-').toLowerCase();const rows=safeList.map(item=>{const whatsapp=cleanText(item.whatsapp);const wa=whatsapp?customerWhatsAppLink({whatsapp}):'';return '<tr data-order-row data-search="'+escapeHtml([item.code,item.name,whatsapp,item.theme,item.status].join(' ').toLowerCase())+'" data-status="'+escapeHtml(item.status||'')+'"><td><a class="order-link" href="'+escapeHtml(orderLink(item.code,adminToken))+'">#'+escapeHtml(item.code)+'</a></td><td><div class="client-name">'+escapeHtml(item.name||'Sem nome')+'</div><div class="muted">'+escapeHtml(item.theme||'Sem tema')+'</div></td><td>'+(wa?'<a class="wa-link" href="'+escapeHtml(wa)+'" target="_blank" rel="noopener">'+escapeHtml(whatsapp)+'</a>':'<span class="muted">Não informado</span>')+'</td><td>'+escapeHtml(new Date(item.createdAt).toLocaleString('pt-BR'))+'</td><td><span class="status-pill status-'+statusSlug(item.status)+'">'+escapeHtml(item.status||'novo')+'</span></td><td>'+escapeHtml(item.total||settings.price)+'</td><td><div class="row-actions"><a class="mini-btn" href="'+escapeHtml(orderLink(item.code,adminToken))+'">Abrir</a><a class="mini-btn danger" href="/painel?token='+encodeURIComponent(adminToken)+'&apagar='+encodeURIComponent(item.code)+'" onclick="return confirm(\'Apagar o pedido '+escapeHtml(item.code)+' e todas as fotos/respostas?\')">Apagar</a></div></td></tr>'}).join('');const cartRows=abandoned.map(item=>{const age=minutesSince(item.updatedAt);const recovery=recoveryWhatsAppLink(item,settings);const stepLabel=['A criança','A história','Personagens','Personalização','Finalizar'][Math.max(0,Math.min(4,Number(item.step)||0))]||'Briefing';return '<tr><td><strong>#'+escapeHtml(item.cartId||'RASCUNHO')+'</strong><div class="cart-age">'+(age<60?age+' min sem atividade':Math.floor(age/60)+' h sem atividade')+'</div></td><td><div class="client-name">'+escapeHtml(item.name||'Cliente não identificado')+'</div><div class="muted">'+escapeHtml(item.theme||'Tema ainda não escolhido')+'</div></td><td>'+escapeHtml(stepLabel)+'</td><td><div class="cart-progress"><span style="width:'+Math.max(1,Math.min(100,Number(item.progress)||0))+'%"></span></div><div class="cart-age">'+escapeHtml(String(item.progress||0))+'% preenchido</div></td><td>'+ (item.whatsapp?escapeHtml(item.whatsapp):'<span class="muted">Ainda não informado</span>') +'</td><td>'+(recovery?'<a class="mini-btn cart-recover" href="'+escapeHtml(recovery)+'" target="_blank" rel="noopener">Recuperar no WhatsApp</a>':'<span class="muted">Sem contato para recuperação</span>')+'</td></tr>'}).join('');const storage=settings.storagePersistent?'<span class="storage-ok">● Armazenamento persistente ativo</span>':'<span class="storage-warn">● Armazenamento temporário</span>';const panelScript='<script>(function(){var q=document.getElementById("admin-search"),f=document.getElementById("admin-status-filter"),rows=[].slice.call(document.querySelectorAll("[data-order-row]")),count=document.getElementById("admin-visible-count");function apply(){var term=(q.value||"").trim().toLowerCase(),status=f.value,visible=0;rows.forEach(function(row){var ok=(!term||row.dataset.search.indexOf(term)>-1)&&(!status||row.dataset.status===status);row.style.display=ok?"":"none";if(ok)visible++});count.textContent=visible+" pedido"+(visible===1?"":"s")+" exibido"+(visible===1?"":"s")}q.addEventListener("input",apply);f.addEventListener("change",apply);apply()})()</script>';const carts='<div class="cart-head" id="carrinhos"><div><h2>Carrinhos abandonados</h2><p>Rascunhos sem atividade há pelo menos 30 minutos e que ainda não viraram pedido.</p></div><div class="admin-count">'+counts.abandonados+' abandonado'+(counts.abandonados===1?'':'s')+'</div></div>'+(settings.storagePersistent?'':'<div class="cart-alert"><strong>Atenção:</strong> sem armazenamento persistente, os carrinhos podem desaparecer quando a função reiniciar ou houver novo deploy.</div>')+'<section class="admin-table-card">'+(cartRows?'<table class="admin-table"><thead><tr><th>Carrinho</th><th>Cliente</th><th>Etapa</th><th>Progresso</th><th>WhatsApp</th><th>Recuperação</th></tr></thead><tbody>'+cartRows+'</tbody></table>':'<div class="admin-empty"><strong>Nenhum carrinho abandonado agora.</strong><br>Rascunhos recentes só aparecem aqui depois de 30 minutos sem atividade.</div>')+'</section>';return adminLayoutHtml('<div class="admin-heading"><div><h1>Dashboard de pedidos</h1><p>Acompanhe clientes, briefings, fotos, produção e oportunidades de recuperação.</p></div><div>'+storage+'</div></div><section class="metrics"><div class="metric"><span>Visitas</span><strong>'+counts.visitas+'</strong></div><div class="metric"><span>Hoje</span><strong>'+counts.hoje+'</strong></div><div class="metric"><span>Pedidos</span><strong>'+counts.total+'</strong></div><div class="metric"><span>Novos</span><strong>'+counts.novo+'</strong></div><div class="metric"><span>Em produção</span><strong>'+counts.producao+'</strong></div><div class="metric"><span>Pagos</span><strong>'+counts.pago+'</strong></div><div class="metric"><span>Enviados</span><strong>'+counts.enviado+'</strong></div><div class="metric"><span>Abandonados</span><strong>'+counts.abandonados+'</strong></div></section>'+funnelSection+'<section class="admin-toolbar"><input class="admin-input" id="admin-search" type="search" placeholder="Buscar por cliente, código, WhatsApp ou tema"><select class="admin-select" id="admin-status-filter"><option value="">Todos os status</option>'+ORDER_STATUSES.map(status=>'<option value="'+escapeHtml(status)+'">'+escapeHtml(status)+'</option>').join('')+'</select><div class="admin-count" id="admin-visible-count"></div></section><section class="admin-table-card" id="pedidos">'+(rows?'<table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>WhatsApp</th><th>Recebido</th><th>Status</th><th>Valor</th><th>Ações</th></tr></thead><tbody>'+rows+'</tbody></table>':'<div class="admin-empty"><strong>Nenhum pedido recebido ainda.</strong><br>Os novos pedidos aparecerão aqui automaticamente.</div>')+'</section>'+carts+'<p class="note" style="margin-top:18px">Recuperações são manuais. Use o WhatsApp apenas quando o cliente tiver informado o número durante o preenchimento.</p>',settings,adminToken,'dashboard','Dashboard',panelScript)}
function orderNotFoundHtml(){return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pedido não encontrado</title><style>'+ORDER_CSS+'</style></head><body><h1>Pedido não encontrado</h1><p class="note">Este link está incompleto, expirou ou o pedido foi apagado. Peça um novo link para a loja pelo WhatsApp.</p></body></html>'}
// Cenas de produção (briefing técnico): exibidas apenas na visão do administrador.
function briefingScenes(briefing){const data=briefing||{};const name=cleanText(data.name)||'a criança';const theme=(cleanText(data.theme)||'aventura').toLowerCase();const feeling=(cleanText(data.feeling)||'amizade').toLowerCase();const cast=(Array.isArray(data.cast)?data.cast:[]).map(item=>cleanText(item&&item.name)+(item&&item.detail?' ('+cleanText(item.detail)+')':''));const years=data.years===''||data.years===undefined?'':', '+data.years+' anos';const base=`Ilustração infantil em estilo ${cleanText(data.style)||'cartoon mágico'}. Personagem principal: ${name}${years}. Preservar a identidade da foto de referência, idade e traços naturais. ${data.outfit==='original'?'Manter a roupa da foto.':'Criar uma roupa coerente com a aventura e mantê-la em todas as páginas.'} Tema: ${cleanText(data.theme)}. ${cast.length?'Elenco de apoio: '+cast.join('; ')+'. ':''}Lição da história: ${feeling}.${cleanText(data.objective)?' Propósito do livro: '+cleanText(data.objective)+'.':''} Idioma do texto final: ${cleanText(data.language)||'português'}. Sem texto, sem marca d'água. Anatomia correta. Composição quadrada.`;const outline=[['Capa',`${name} e a aventura de ${theme}. Apresentar o personagem principal e o mundo da história.`],['Um dia especial',`Apresentar ${name} na rotina e mostrar uma característica: ${cleanText(data.personality)||'curiosidade e imaginação'}.`],['O convite',`Um acontecimento desperta o interesse de ${name} pelo universo de ${theme}.`],['Um mundo para descobrir',`O personagem chega ao cenário da aventura, com detalhes sensoriais adequados à faixa ${cleanText(data.age)}.`],['Um novo encontro',`Apresentar ${cast.length?cast.map(item=>item.split(' (')[0]).join(' e '):'um amigo original da aventura'} e criar uma oportunidade de cooperação.`],['O desafio',`Criar um conflito leve e apropriado para a idade, que permita explorar ${feeling}.`],['A primeira tentativa',`Mostrar a primeira tentativa de resolver o desafio e o que ${name} aprende com ela.`],['Uma boa ideia',`A criança encontra uma solução usando ${feeling} e participa ativamente da decisão.`],['A grande conquista',`Mostrar ${name} como protagonista da solução, com apoio dos amigos e sem resolver tudo por magia.`],['O que ficou no coração',`Encerrar com uma cena acolhedora, reforçando ${feeling}.${cleanText(data.details)?' Incorporar, quando coerente: '+cleanText(data.details)+'.':''}`]];return outline.map(item=>({title:item[0],description:item[1],prompt:base+' Cena: '+item[1]}))}
function adminBriefingHtml(record){const briefing=record.briefing||{};const rows=orderLines(briefing).filter(entry=>cleanText(entry[1])).map(entry=>'<dt>'+escapeHtml(entry[0])+'</dt><dd>'+escapeHtml(entry[1])+'</dd>').join('');const characters=[{name:briefing.name||'Personagem principal',kind:'Principal',detail:briefing.years===''||briefing.years===undefined?'':briefing.years+' anos',photo:briefing.photo||''},...(Array.isArray(briefing.cast)?briefing.cast:[])];const characterCards=characters.map((item,index)=>'<div class="card"><h3>'+escapeHtml(item.name||'Personagem')+'</h3>'+(cleanText(item.photo)?'<img class="photo" src="'+escapeHtml(item.photo)+'" alt="Foto de '+escapeHtml(item.name||'personagem')+'">':'<p class="note">Sem foto de referência</p>')+'<dl><dt>Tipo</dt><dd>'+escapeHtml(index===0?'Personagem principal':item.kind||'Personagem')+'</dd><dt>Detalhe</dt><dd>'+escapeHtml(item.detail||'—')+'</dd></dl></div>').join('');return '<section class="admin-section"><h2>Briefing completo do cliente</h2><div class="card"><dl><dt>Pedido</dt><dd>'+escapeHtml(record.code)+'</dd><dt>Recebido em</dt><dd>'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</dd>'+rows+'</dl></div></section><section class="admin-section"><h2>Personagens que vão aparecer</h2><div class="photo-grid">'+characterCards+'</div></section>'}
function adminProductionHtml(record,settings){const story=record.story;const statusOptions=ORDER_STATUSES.map(status=>'<option value="'+escapeHtml(status)+'" '+(record.status===status?'selected':'')+'>'+escapeHtml(status)+'</option>').join('');const statusBox='<div class="status-box"><label for="admin-order-status">STATUS DO PEDIDO</label><div class="status-row"><select id="admin-order-status">'+statusOptions+'</select><button id="admin-save-status" type="button">Salvar</button></div><p class="note" id="admin-status-save"></p></div>';const summaryBlock='<section class="admin-section"><h2>Resumo do pedido</h2><div class="card"><pre id="summary">'+escapeHtml(record.summary||'')+'</pre><div class="actions"><button class="secondary" id="copy" type="button">Copiar resumo</button></div></div></section>';const storyBlock=story?'<section class="admin-section"><h2>História ('+escapeHtml(String(story.provider))+(story.mock?' · demonstração':'')+')</h2><div class="card"><dl><dt>Título</dt><dd>'+escapeHtml(story.title)+'</dd><dt>Páginas</dt><dd>'+story.pages.length+'</dd><dt>Prompts</dt><dd>'+story.illustrations.length+'</dd></dl><div class="actions"><button class="primary" id="admin-generate" type="button">Gerar de novo</button><a class="secondary" href="'+escapeHtml('/api/admin/pdf?code='+record.code+'&token='+settings.admin)+'">Baixar PDF</a></div><p class="note" id="admin-status"></p></div><div class="card"><pre>'+escapeHtml(story.pages.map(page=>'P'+page.page+': '+page.text).join('\n\n'))+'</pre></div><h2>Prompts de ilustração</h2><div class="card"><pre>'+escapeHtml(story.illustrations.map(item=>'Página '+item.page+': '+item.prompt).join('\n\n'))+'</pre></div></section>':'<section class="admin-section"><h2>Produção</h2><div class="card"><p class="note">A história deste pedido ainda não foi gerada.</p><div class="actions"><button class="primary" id="admin-generate" type="button">Gerar história (30 páginas)</button></div><p class="note" id="admin-status"></p></div></section>';const sheets='<section class="admin-section"><h2>Cenas de produção</h2><div class="card"><pre>'+escapeHtml(briefingScenes(record.briefing).map(scene=>scene.title+'\n  '+scene.description+'\n  Prompt: '+scene.prompt).join('\n\n'))+'</pre></div></section>';return '<div class="admin-order-head"><div><a class="admin-back" href="/painel?token='+encodeURIComponent(settings.admin)+'">← Voltar ao painel</a><h2 style="font-size:24px;margin:0">Pedido #'+escapeHtml(record.code)+'</h2><p class="note">Visão administrativa · briefing, fotos e produção</p></div>'+statusBox+'</div>'+adminBriefingHtml(record)+summaryBlock+storyBlock+sheets}
function orderPageHtml(record,settings,origin,isAdmin){const briefing=record.briefing||{};const link=origin+orderLink(record.code,record.accessToken||'');const summary=record.summary||orderSummary(briefing,record.code,settings,link);const photo=cleanText(briefing.photo)?'<img class="photo" src="'+escapeHtml(briefing.photo)+'" alt="Foto de referência da criança">':'<p class="note">Nenhuma foto foi anexada a este pedido.</p>';const rows=orderLines(briefing).filter(entry=>cleanText(entry[1])).map(entry=>'<dt>'+escapeHtml(entry[0])+'</dt><dd>'+escapeHtml(entry[1])+'</dd>').join('');const production=isAdmin?adminProductionHtml(record,settings):'';const clientNote=isAdmin?'':'<p class="note">Este é o seu pedido. A loja usa a foto e as respostas para produzir o livro e combina o pagamento pelo WhatsApp. Arquivos de produção não são exibidos aqui.</p>';const adminScript=isAdmin?'<script>var statusSelect=document.getElementById("admin-order-status"),statusSave=document.getElementById("admin-save-status"),statusMsg=document.getElementById("admin-status-save");if(statusSave)statusSave.onclick=function(){statusSave.disabled=true;if(statusMsg)statusMsg.textContent="Salvando…";fetch("'+escapeHtml('/api/admin/status?code='+record.code+'&token='+settings.admin)+'",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({status:statusSelect.value})}).then(function(r){return r.json()}).then(function(payload){statusSave.disabled=false;if(payload&&payload.ok){if(statusMsg)statusMsg.textContent="Status atualizado.";setTimeout(function(){window.location.reload()},500)}else if(statusMsg)statusMsg.textContent=payload&&payload.error?payload.error:"Não foi possível salvar."}).catch(function(){statusSave.disabled=false;if(statusMsg)statusMsg.textContent="Não foi possível salvar."})};var copy=document.getElementById("copy");if(copy)copy.onclick=function(){navigator.clipboard.writeText(document.getElementById("summary").textContent).then(function(){copy.textContent="Resumo copiado"})};var generate=document.getElementById("admin-generate");if(generate)generate.onclick=function(){var status=document.getElementById("admin-status");generate.disabled=true;if(status)status.textContent="Gerando a história…";fetch("'+escapeHtml('/api/admin/book?code='+record.code+'&token='+settings.admin)+'",{method:"POST"}).then(function(r){return r.json()}).then(function(payload){if(payload&&payload.story){window.location.reload()}else{generate.disabled=false;if(status)status.textContent=payload&&payload.error?payload.error:"Não foi possível gerar."}}).catch(function(){generate.disabled=false;if(status)status.textContent="Não foi possível gerar."})};</script>':'';const clientContent='<span class="badge">'+escapeHtml(record.status)+'</span><h1>Pedido '+escapeHtml(record.code)+'</h1><p class="code">'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</p><div class="actions">'+(customerWhatsAppLink(briefing)?'<a class="primary" href="'+escapeHtml(customerWhatsAppLink(briefing))+'" target="_blank" rel="noopener">Falar com o cliente</a>':'')+'<a class="secondary" href="'+escapeHtml('https://wa.me/?text='+encodeURIComponent(summary))+'" target="_blank" rel="noopener">Encaminhar pedido</a></div><div class="card">'+photo+'<dl>'+rows+'</dl></div>'+((settings.pixCopyPaste||settings.pix)?'<div class="card"><h2 style="margin-top:0">Pagamento via Pix</h2><p class="note">Valor: <strong>'+escapeHtml(settings.price)+'</strong></p>'+(settings.pixCopyPaste?'<p class="pix" style="font-size:11px">'+escapeHtml(settings.pixCopyPaste)+'</p>'+(settings.pix?'<p class="note">Chave Pix: <strong>'+escapeHtml(settings.pix)+'</strong></p>':'')+'<p class="note">Use o Pix Copia e Cola no app do seu banco.</p>':'<p class="pix">'+escapeHtml(settings.pix)+'</p><p class="note">Use esta chave Pix para pagar.</p>')+'</div>':'<div class="card"><h2 style="margin-top:0">Cobrança</h2><p class="note">Valor: '+escapeHtml(settings.price)+' · combine o pagamento pelo WhatsApp.</p></div>')+production+clientNote+'<p class="note">Link privado do pedido: quem tiver este endereço vê a foto e os dados. Não compartilhe fora da produção e apague o pedido depois de entregar.</p>';const top=isAdmin?'<header class="admin-topbar"><div class="admin-brand"><div class="admin-logo">FC</div><div>FC Livros Mágicos<br><span style="font-size:12px;color:#cbd5e1;font-weight:600">Pedido administrativo</span></div></div><div class="admin-topmeta">'+escapeHtml(new Date(record.createdAt).toLocaleString('pt-BR'))+'</div></header><main class="admin-shell">':'';const bottom=isAdmin?'</main>':'';return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pedido '+escapeHtml(record.code)+' — '+escapeHtml(settings.shop)+'</title><style>'+ORDER_CSS+(isAdmin?ADMIN_CSS:'')+'</style></head><body'+(isAdmin?' class="admin-body"':'')+'>'+top+clientContent+bottom+adminScript+'</body></html>'}
